_FALLBACK_SRC = '# Exact action format: list[tuple[int, int, int]], [(from_node, to_node, count), ...].\n# "revenue_p = sum of node_value[i] over all nodes i that player p owns"\n# "upkeep_p = UPKEEP * (UNITS_PER_PLAYER - units of p on its own base)"\n# Ownership persists without units. Capturing requires two consecutive strict\n# majorities; transit units count for no majority. Bases cannot be captured.\n\nTIME_BUDGET = 0.25\n\nN_TURNS = 80\nUNITS_PER_PLAYER = 20\nUPKEEP = 2.0\n\n\ndef payout(values, owned, units_at_base):\n    """The specification\'s exact per-turn profit function."""\n    revenue = sum(value for value, owner in zip(values, owned) if owner)\n    upkeep = UPKEEP * (UNITS_PER_PLAYER - units_at_base)\n    return float(revenue - upkeep)\n\n\ndef preprocess_map(n, edges):\n    """Small, deterministic weighted all-pairs shortest paths."""\n    infinity = 10**9\n    distance = [[infinity] * n for _ in range(n)]\n    adjacency = [[] for _ in range(n)]\n    for u in range(n):\n        distance[u][u] = 0\n    for u, v, length in edges:\n        adjacency[u].append((v, length))\n        adjacency[v].append((u, length))\n        distance[u][v] = length\n        distance[v][u] = length\n    for row in adjacency:\n        row.sort()\n    for k in range(n):\n        for u in range(n):\n            for v in range(n):\n                candidate = distance[u][k] + distance[k][v]\n                if candidate < distance[u][v]:\n                    distance[u][v] = candidate\n    next_hop = [[-1] * n for _ in range(n)]\n    for u in range(n):\n        for v in range(n):\n            if u != v:\n                for neighbor, length in adjacency[u]:\n                    if length + distance[neighbor][v] == distance[u][v]:\n                        next_hop[u][v] = neighbor\n                        break\n    return distance, next_hop, adjacency\n\n\ndef make_plan(obs, distance, next_hop):\n    """One inexpensive scout per affordable node; never initiate a fight."""\n    n = obs["n_nodes"]\n    turn = obs["turn"]\n    remaining = max(0, N_TURNS - turn)\n    base = obs["player_base"]\n    enemy_base = obs["opponent_base"]\n    values = obs["node_value"]\n    owned = obs["player_owned"]\n    units = obs["player_units"]\n    leads = obs["player_lead_turns"]\n\n    # Visible garrisons and all announced arrivals are treated as blocking.\n    # There is no proportional revenue sharing in this game: a tied or losing\n    # scout cannot capture, so such opportunities are simply rejected.\n    blocked = [count > 0 for count in obs["opponent_units"]]\n    for _, destination, count, _ in obs.get("opponent_transits", []):\n        if count > 0:\n            blocked[destination] = True\n\n    # Supplies include committed transit units, so launches are not duplicated.\n    # A transit\'s origin is deliberately absent: it cannot be moved this turn.\n    supplies = []\n    for node, count in enumerate(units):\n        if count:\n            supplies.append([node, 0, count, True])\n    for _, destination, count, arrival in obs.get("player_transits", []):\n        if count:\n            supplies.append(\n                [destination, max(0, arrival - turn), count, False]\n            )\n\n    tasks = []\n    for node in range(n):\n        if node in (base, enemy_base) or blocked[node]:\n            continue\n        # High-value nodes support one permanent unit with positive net income.\n        # Low-value nodes are captured and immediately vacated on later calls.\n        if not owned[node] or values[node] > UPKEEP:\n            tasks.append(node)\n\n    available = [s[2] for s in supplies]\n    assigned = set()\n    orders = []\n\n    # Retain an existing scout first. This both completes the second majority\n    # turn and prevents equivalent assignments from exchanging scouts.\n    for index, (source, delay, _, movable) in enumerate(supplies):\n        if movable and source in tasks and available[index] > 0:\n            assigned.add(source)\n            available[index] -= 1\n\n    candidates = []\n    for target in tasks:\n        if target in assigned:\n            continue\n        value = values[target]\n        for index, (source, delay, _, movable) in enumerate(supplies):\n            travel = delay + distance[source][target]\n            # Landing is at end of travel-1; the second lead is at end of\n            # travel. A stationary unit needs one or two more turn ends.\n            if travel == 0:\n                capture_delay = 0 if leads[target] >= 1 else 1\n            else:\n                capture_delay = travel\n            if owned[target]:\n                paying_turns = remaining\n            else:\n                paying_turns = max(0, remaining - capture_delay)\n\n            if value > UPKEEP:\n                # Charge all remaining upkeep, including outbound travel.\n                cost = UPKEEP * remaining\n            else:\n                # Conservative complete capture-and-return journey cost.\n                # A trip is rejected unless its return also fits the horizon.\n                trip = travel + 1 + distance[target][base]\n                if trip > remaining:\n                    continue\n                cost = UPKEEP * trip\n\n            benefit = value * paying_turns - cost\n            # Require a substantial positive surplus, not merely break-even.\n            if benefit < max(6.0, 0.15 * cost):\n                continue\n            # Nearest first; stronger surplus breaks equal-distance ties.\n            candidates.append((travel, -benefit, target, index))\n\n    candidates.sort()\n    for _, _, target, index in candidates:\n        if target in assigned or available[index] <= 0:\n            continue\n        source, _, _, movable = supplies[index]\n        available[index] -= 1\n        assigned.add(target)\n        if movable and source != target:\n            hop = next_hop[source][target]\n            if hop >= 0:\n                orders.append((source, hop, 1))\n\n    # All unused scouts go directly home along weighted shortest paths.\n    # Units at home never move unless assigned a profitable capture above.\n    for index, (source, _, _, movable) in enumerate(supplies):\n        count = available[index]\n        if movable and source != base and count > 0:\n            hop = next_hop[source][base]\n            if hop >= 0:\n                orders.append((source, hop, count))\n    return orders\n\n\ndef legal_action(plan, units, adjacency):\n    """Aggregate, then replay every move against start-of-turn availability."""\n    combined = {}\n    for source, destination, count in plan:\n        key = (int(source), int(destination))\n        combined[key] = combined.get(key, 0) + int(count)\n\n    available = list(units)\n    n = len(available)\n    result = []\n    for (source, destination), requested in sorted(combined.items()):\n        if not (0 <= source < n and 0 <= destination < n):\n            continue\n        if source == destination or requested <= 0:\n            continue\n        if not any(v == destination for v, _ in adjacency[source]):\n            continue\n        count = min(requested, available[source])\n        if count > 0:\n            result.append((int(source), int(destination), int(count)))\n            available[source] -= count\n    return result\n\n\nclass Strategy:\n    def __init__(self, player_id: int) -> None:\n        self.player_id = player_id\n        self.map_key = None\n        self.map_data = None\n\n    def act(self, obs):\n        n = obs.get("n_nodes", 0)\n        if n <= 0 or obs.get("turn", N_TURNS) >= N_TURNS:\n            return []\n\n        # Only static map data is cached. Planning remains independent of all\n        # previous calls, including skipped turns and first calls after turn 0.\n        edges = obs.get("edges", [])\n        key = (n, tuple(tuple(edge) for edge in edges))\n        if key != self.map_key:\n            self.map_data = preprocess_map(n, edges)\n            self.map_key = key\n\n        distance, next_hop, adjacency = self.map_data\n        plan = make_plan(obs, distance, next_hop)\n        return legal_action(plan, obs["player_units"], adjacency)\n'
